SemaphoreHandle_t rxSem;  // 信号量句柄

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART1_UART_Init();

    rxSem = xSemaphoreCreateBinary();  // 创建二值信号量

    xTaskCreate(RxTask, "Rx", 256, NULL, 3, NULL);
    HAL_UART_Receive_IT(&huart1, &rxByte, 1);
    vTaskStartScheduler();
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef* huart) {
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    // 中断中释放信号量
    xSemaphoreGiveFromISR(rxSem, &xHigherPriorityTaskWoken);
    portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
    HAL_UART_Receive_IT(&huart1, &rxByte, 1);
}

void RxTask(void* arg) {
    while (1) {
        // 等待信号量(阻塞)
        xSemaphoreTake(rxSem, portMAX_DELAY);
        // 处理接收数据
        processRxData(rxByte);
    }
}

SemaphoreHandle_t uartMutex;

void initMutex(void) {
    uartMutex = xSemaphoreCreateMutex();
}

// 多任务安全打印
void safePrintf(const char* fmt, ...) {
    xSemaphoreTake(uartMutex, portMAX_DELAY);
    // 临界区
    va_list args;
    va_start(args, fmt);
    vprintf(fmt, args);
    va_end(args);
    xSemaphoreGive(uartMutex);
}

// 多任务保护全局变量
volatile int counter = 0;
void counterTask(void* arg) {
    while (1) {
        xSemaphoreTake(uartMutex, portMAX_DELAY);
        counter++;  // 保护共享变量
        xSemaphoreGive(uartMutex);
        vTaskDelay(100);
    }
}

// 队列传递传感器数据
typedef struct {
    float temp;
    float humi;
} SensorData;

QueueHandle_t dataQueue;

void sensorTask(void* arg) {
    SensorData data;
    while (1) {
        // 读取传感器
        data.temp = readTemp();
        data.humi = readHumi();
        // 发送到队列(等待10tick)
        xQueueSend(dataQueue, &data, 10);
        vTaskDelay(2000);
    }
}

void displayTask(void* arg) {
    SensorData data;
    while (1) {
        // 从队列接收(阻塞等待)
        if (xQueueReceive(dataQueue, &data, portMAX_DELAY)) {
            // 显示数据
            printf("T:%.1f H:%.1f\r\n", data.temp, data.humi);
        }
    }
}

// 创建队列
dataQueue = xQueueCreate(10, sizeof(SensorData));

#define BIT_TEMP   (1 << 0)
#define BIT_HUMI   (1 << 1)

EventGroupHandle_t xEventGroup;

void tempTask(void* arg) {
    while (1) {
        readTemp();
        xEventGroupSetBits(xEventGroup, BIT_TEMP);  // 设置温度就绪
        vTaskDelay(2000);
    }
}

void humiTask(void* arg) {
    while (1) {
        readHumi();
        xEventGroupSetBits(xEventGroup, BIT_HUMI);  // 设置湿度就绪
        vTaskDelay(2000);
    }
}

void processTask(void* arg) {
    while (1) {
        // 等待温度和湿度都就绪(AND模式，自动清除)
        xEventGroupWaitBits(xEventGroup, 
            BIT_TEMP | BIT_HUMI,
            pdTRUE,    // 退出时清除
            pdTRUE,    // AND模式(所有位)
            portMAX_DELAY);
        // 两个都就绪，处理
        processData();
    }
}

// 创建
xEventGroup = xEventGroupCreate();

// 软件定时器
void reportCallback(TimerHandle_t xTimer) {
    // 周期上报数据(回调中不能阻塞)
    sendReport();
}

void timeoutCallback(TimerHandle_t xTimer) {
    // 超时处理
    printf("Timeout!\r\n");
}

int main(void) {
    // ...
    // 创建周期定时器(5秒，周期触发)
    TimerHandle_t reportTimer = xTimerCreate(
        "Report", pdMS_TO_TICKS(5000), pdTRUE, 0, reportCallback);
    xTimerStart(reportTimer, 0);

    // 创建单次定时器(10秒超时)
    TimerHandle_t timeoutTimer = xTimerCreate(
        "Timeout", pdMS_TO_TICKS(10000), pdFALSE, 0, timeoutCallback);
    xTimerStart(timeoutTimer, 0);

    vTaskStartScheduler();
}

// 综合项目代码
QueueHandle_t dataQueue;
SemaphoreHandle_t cmdSem;
SensorData latestData;

void sensorTask(void* arg) {
    SensorData data;
    while (1) {
        dht11Read(&data.temp, &data.humi);
        xQueueSend(dataQueue, &data, 10);
        latestData = data;  // 存最新
        vTaskDelay(2000);
    }
}

void displayTask(void* arg) {
    SensorData data;
    while (1) {
        if (xQueueReceive(dataQueue, &data, portMAX_DELAY)) {
            displayTempHumi(data.temp, data.humi);
        }
    }
}

void reportCallback(TimerHandle_t timer) {
    printf("Report T:%d H:%d\r\n", latestData.temp, latestData.humi);
}

void cmdTask(void* arg) {
    while (1) {
        xSemaphoreTake(cmdSem, portMAX_DELAY);
        // 处理串口命令
        processCommand(rxByte);
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    // ... 初始化外设
    dataQueue = xQueueCreate(5, sizeof(SensorData));
    cmdSem = xSemaphoreCreateBinary();
    TimerHandle_t t = xTimerCreate("Report", pdMS_TO_TICKS(5000), 
                                   pdTRUE, 0, reportCallback);
    xTimerStart(t, 0);
    xTaskCreate(sensorTask, "Sensor", 256, NULL, 3, NULL);
    xTaskCreate(displayTask, "Display", 256, NULL, 2, NULL);
    xTaskCreate(cmdTask, "Cmd", 256, NULL, 2, NULL);
    vTaskStartScheduler();
}
